                            graph[i][j] += 1
            elif gate[0] == 'OR':
                for i in gate[1]:
                    for j in range(n):
                        if j not in gate[1]:
                            graph[i][j] += 1
        return graph

    def eta_invariant(graph):
        n = len(graph)
        total_edges = sum(sum(row) for row in graph) // 2
        max_degree = max(max(row) for row in graph)
        return Fraction(total_edges, max_degree)

    def monotone_width(circuit):
